  const peopleCards = people.map((group, index) => { const latest = group.conversations[0], channel = find('connections', latest.connectionId), unread = group.conversations.filter(c => c.unread).length, count = group.conversations.length; return `<button class="comment-person-card ${selectedGroup?.key === group.key ? 'active' : ''}" data-action="open-conversation" data-id="${e(latest.id)}">${commentAvatar(group.person, ['sage', 'peach', 'lilac'][index % 3])}<div class="grow"><div class="comment-person-name"><strong>${e(group.person?.name || 'Người dùng Facebook')}</strong><time>${time(group.lastAt)}</time></div><p>${e(latest.lastMessage || 'Bình luận Facebook')}</p><small>${social(channel?.provider || 'facebook')} ${e(connectionName(channel))} · ${count} bình luận</small></div>${unread ? `<b>${unread}</b>` : ''}</button>`; }).join('');
  const context=conv?commentContexts.get(conv.id)||localCommentDetail(conv):null,replyTarget=conv?commentReplyTargets.get(conv.id)||'current':'current';
  const commentCards = messages.filter(message => !message.deletedAt).map(message => { const messageConv = find('conversations', message.conversationId), messageChannel = find('connections', messageConv?.connectionId), incoming = message.direction === 'incoming', failed = !incoming && ['failed','unknown'].includes(message.status); return `<article data-message="${e(message.id)}" class="comment-message ${incoming ? 'incoming' : 'outgoing'} ${failed ? 'failed' : ''}">${incoming ? commentAvatar(customer, 'sage') : ''}<div class="comment-message-content"><div class="comment-message-bubble">${!incoming&&message.replyToExternalId?`<small class="comment-reply-target-label">${message.replyTarget==='parent'?'Trả lời bình luận gốc':'Trả lời bình luận đang xem'}</small>`:''}${message.text ? `<p>${e(message.text)}</p>` : `<p>${failed ? 'Media chưa gửi được' : 'Đã gửi media'}</p>`}${(message.attachments || []).map(a => a.type === 'video' ? `<video src="${e(a.url)}" controls></video>` : `<img src="${e(a.url)}" alt="Ảnh bình luận">`).join('')}</div><div class="comment-message-meta"><time>${time(message.createdAt)}</time>${messageConv?.postUrl?`<a class="text-btn" href="${e(messageConv.postUrl)}" target="_blank" rel="noopener noreferrer">Mở bài gốc ↗</a>`:''}${incoming ? `${messageChannel?.provider==='facebook'||messageChannel?.mode==='demo'?`<button type="button" class="text-btn ${message.liked ? 'active' : ''}" data-action="react-comment" data-id="${e(message.id)}">${icon('heart', 13)}${message.liked ? 'Đã thích' : 'Thích'}</button>`:''}<button type="button" class="text-btn" data-action="comment-reply-current" data-id="${e(messageConv?.id || '')}">${icon('send', 12)}Trả lời</button>${['facebook','instagram'].includes(messageChannel?.provider)||messageChannel?.mode==='demo'?`<button type="button" class="text-btn danger-text" data-action="delete-comment" data-id="${e(message.id)}">${icon('close', 12)}Xóa</button>`:''}` : `<span>${failed ? `${message.status==='unknown'?'Cần kiểm tra trên nền tảng':'Thất bại'}${message.error ? ' · ' + e(message.error) : ''}` : message.status==='sending'?'Đang gửi':`Đã gửi · ${e(connectionName(messageChannel))}`}</span>`}</div></div></article>`; }).join('') || empty('Chưa có nội dung', 'Bình luận của người này sẽ xuất hiện tại đây.');
  const detail = conv ? `<form class="chat-compose" id="reply-form" data-id="${conv.id}"><div class="row between"><span class="small muted">Trả lời công khai trên ${e(connectionName(ch))} · ${ch?.provider==='threads'?'văn bản (tối đa 500 ký tự)':ch?.provider==='instagram'?'văn bản':'văn bản hoặc 1 ảnh/video'}</span><input type="hidden" name="note"><input type="hidden" name="replyTarget" value="${e(replyTarget)}"></div><div class="comment-reply-destination">${replyTarget==='parent'?'Trả lời bình luận gốc của '+e(context?.parent?.name||'khách hàng'):'Trả lời bình luận đang xem'}</div><div id="comment-reply-preview">${commentPreviewHTML()}</div><textarea name="text" placeholder="Trả lời ${e(customer?.name || 'bình luận')}…" aria-label="Nội dung trả lời"></textarea><div class="row between"><div class="row" style="gap:5px">${ch?.provider==='facebook'||ch?.mode==='demo'?`<label class="icon-btn" for="comment-upload" aria-label="Thêm ảnh hoặc video" title="Thêm ảnh hoặc video">${icon('image', 18)}</label><input id="comment-upload" type="file" class="hidden" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime">`: ''}<button type="button" class="icon-btn" data-action="reply-templates" data-id="${conv.id}" aria-label="Mẫu trả lời">${icon('note', 18)}</button></div><button class="btn primary" type="submit">Gửi ${icon('send', 15)}</button></div></form>` : empty('Chọn một bình luận', 'Bấm Trả lời bên dưới bong bóng bình luận để bắt đầu.');
