  return title('Bình luận', 'Theo dõi và trả lời theo từng người bình luận.') + `<div class="toolbar comment-toolbar">${tabs([['all', 'Tất cả'], ['unread', 'Chưa đọc'], ['open', 'Đang mở'], ['pending', 'Đang chờ'], ['resolved', 'Đã xử lý']])}${search('Tìm người bình luận…')}<select id="comment-channel" aria-label="Lọc kênh bình luận"><option value="">Tất cả kênh</option>${S.connections.filter(c=>c.status==='connected').map(c=>`<option value="${e(c.id)}" ${commentChannel===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select>${btn('Đồng bộ bình luận','sync-comments','refresh')}</div><div id="comment-sync-status" class="comment-sync-status" role="status"></div><div class="comments-workspace ${selectedGroup ? 'has-post' : ''} ${selectedConversation ? 'has-selection' : ''}"><aside class="comment-post-list"><div class="comment-column-title"><strong>Bình luận</strong><span>${people.length}</span></div>${peopleCards || empty('Chưa có người bình luận', 'Bình luận của các kênh hỗ trợ sẽ xuất hiện sau khi đồng bộ.')}</aside><section class="comment-work-area">${chatHead}<div class="comment-feed-scroll"><div id="comment-context-slot" data-id="${e(conv?.id||'')}">${context?commentContextHTML(context,replyTarget):''}</div>${commentCards}</div><div class="chat comment-detail">${detail}</div></section></div>`;
