function assetPreviews() { return draftAssets.map(id => { const a = find('assets', id); return a ? `<div class="upload-item">${a.type === 'video' ? `<video src="${e(a.url)}" muted></video>` : a.type === 'audio' ? `<audio src="${e(a.url)}" controls preload="metadata"></audio>` : `<img src="${e(a.url)}" alt="${e(a.name)}">`}<button type="button" data-action="remove-asset" data-id="${id}" aria-label="Bỏ media">×</button></div>` : ''; }).join(''); }
