async function uploadFiles(files, composer = false) {
  for (const file of files) {
    const notice = document.createElement('p'); notice.className = 'help-text upload-progress'; notice.textContent = `Đang tải ${file.name}…`; ($('.modal-body') || $('#page')).append(notice); try {
      const asset = file.size > 4 * 1024 * 1024
        ? await uploadFileInChunks(file, notice)
        : await new Promise((resolve, reject) => { const xhr = new XMLHttpRequest(); xhr.open('POST', '/api/upload'); xhr.setRequestHeader('Content-Type', file.type); xhr.setRequestHeader('X-Filename', encodeURIComponent(file.name)); xhr.setRequestHeader('X-CSRF-Token', S.user.csrf); xhr.upload.onprogress = p => { if (p.lengthComputable) notice.textContent = `Đang tải ${file.name} · ${Math.round(p.loaded / p.total * 100)}%`; }; xhr.onload = () => finishUpload(xhr,resolve,reject); xhr.onerror = () => reject(new Error('Mất kết nối khi upload. Vui lòng chọn lại file để tải.')); xhr.onabort=()=>reject(new Error('Upload đã bị hủy.'));xhr.send(file); }); S.assets.unshift(asset); if (composer) { draftAssets.push(asset.id); syncContentType(asset); $('#upload-list').innerHTML = assetPreviews(); $('#preview-media').innerHTML = thumb({ assets: draftAssets }, 'card-cover'); } toast('Đã lưu ' + file.name);
    } catch (err) { toast(err.message, true); } finally { notice.remove(); }
  } if (!composer) await refresh();
}
async function uploadAsset(file,conversationId) {
  const notice = document.createElement('p'); notice.className = 'help-text upload-progress'; notice.textContent = `Đang tải ${file.name}…`; ($('.modal-body') || $('#page')).append(notice); try {
    return await new Promise((resolve, reject) => { const xhr = new XMLHttpRequest(); xhr.open('POST', '/api/upload'+(conversationId?'?conversationId='+encodeURIComponent(conversationId):'')); xhr.setRequestHeader('Content-Type', file.type); xhr.setRequestHeader('X-Filename', encodeURIComponent(file.name)); xhr.setRequestHeader('X-CSRF-Token', S.user.csrf); xhr.onload = () => finishUpload(xhr,resolve,reject); xhr.onerror = () => reject(new Error('Mất kết nối khi upload. Vui lòng chọn lại file để tải.')); xhr.onabort=()=>reject(new Error('Upload đã bị hủy.'));xhr.send(file); });
  } finally { notice.remove(); }
}
