function chooseUpload() { const input = document.createElement('input'); input.type = 'file'; input.accept = 'image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime,audio/mpeg,audio/wav,audio/x-wav,audio/ogg,audio/mp4'; input.multiple = true; input.onchange = () => uploadFiles([...input.files]); input.click(); }
