let notificationUser = '', notificationSeen = new Set();
function updateChatNotifications(rows) { if (!S?.user) return; if (notificationUser !== S.user.id) { notificationUser = S.user.id; notificationSeen = new Set(rows.map(n => n.id)); } updateDeviceBadge(rows.filter(n => !n.read).length + S.conversations.filter(c => c.unread && S.notificationConversationIds?.includes(c.id)).length); const button = document.querySelector('[data-action=notifications]'); if (button) { let dot = button.querySelector('.notification-dot'); if (rows.some(n => !n.read) && !dot) { dot = document.createElement('i'); dot.className = 'notification-dot'; dot.style.cssText = 'position:absolute;top:5px;right:5px;background:red;width:8px;height:8px;border-radius:50%'; button.append(dot); } if (!rows.some(n => !n.read)) dot?.remove(); } for (const n of rows) { if (!notificationSeen.has(n.id) && !n.read && (n.id.startsWith('chat-reminder:') || n.id.startsWith('chat-reminder-error:') || n.id.startsWith('care-message:') || n.id.startsWith('customer-purge:') || n.id.startsWith('copy:') || n.id.startsWith('copy-error:'))) { toast(n.title + ': ' + n.body); notificationSound(); } notificationSeen.add(n.id); } }
let pollingNotifications = false, notificationRevision = '', notificationRevisionUser = '', notificationRetryAt = 0, notificationFailures = 0;
setInterval(async () => { if (!S?.user || pollingNotifications || document.hidden || Date.now() < notificationRetryAt) return; pollingNotifications = true; const userId = S.user.id; if (notificationRevisionUser !== userId) { notificationRevisionUser = userId; notificationRevision = ''; } try { const result = await api('/notifications?since=' + encodeURIComponent(notificationRevision)); if (S?.user?.id !== userId) return; notificationRevision = result.revision; notificationFailures = 0; notificationRetryAt = 0; if (!result.unchanged) { S.notifications = result.rows; updateChatNotifications(result.rows); } } catch { notificationFailures++; notificationRetryAt = Date.now() + Math.min(60000, 2000 * 2 ** Math.min(notificationFailures, 5)); } finally { pollingNotifications = false; } }, 2000);

async function enhanceCommentStatus(){
 if(route!=='comments'||commentSyncLoading)return;commentSyncLoading=true;
 try{if(Date.now()-commentSyncAt>5000){commentSyncRows=await api('/comments/status');commentSyncAt=Date.now();}
 const box=$('#comment-sync-status');if(!box)return;
 let details=box.querySelector('details');if(!details){details=document.createElement('details');details.innerHTML='<summary></summary><div class="comment-sync-content"></div>';box.append(details);}
 const summary=details.querySelector('summary'),content=details.querySelector('.comment-sync-content');summary.textContent='Trạng thái đồng bộ kênh'+(commentSyncRows.some(c=>c.status==='error')?' · ⚠ Cần kiểm tra quyền':'');
 const live=new Set();for(const c of commentSyncRows){live.add(c.id);let row=content.querySelector(`[data-channel-id="${CSS.escape(c.id)}"]`);if(!row){row=document.createElement('div');row.dataset.channelId=c.id;content.append(row);}const html=`${social(c.provider)} <strong>${e(c.name)}</strong> · ${c.supported?e(c.status==='error'?'Lỗi đồng bộ: '+c.error:c.status==='ready'?(c.backfilling?'Đang tải lịch sử':'Đã đồng bộ')+' · '+c.count+' bình luận':'Chờ đồng bộ'):'Kết nối này chưa hỗ trợ API bình luận'}${c.status==='error'&&/quyền|permission|code 10|code 190|token/i.test(c.error)&&S.providers[c.provider]?.oauth?btn('Kết nối lại','oauth-connect','refresh','small',c.id):''}`;const className='comment-channel-status '+(c.status==='error'?'error':'');if(row.className!==className)row.className=className;if(row.innerHTML!==html)row.innerHTML=html;content.append(row);}for(const row of [...content.querySelectorAll('[data-channel-id]')])if(!live.has(row.dataset.channelId))row.remove();
 }catch(error){console.warn('Không cập nhật được trạng thái bình luận:',error.message);}finally{commentSyncLoading=false;}
}
setInterval(()=>{if(route==='comments'&&!document.hidden)void enhanceCommentStatus();void enhanceCommentContext();},10000);

function localCommentDetail(c){
 const root=S.messages.find(m=>m.conversationId===c.id&&m.externalId===c.externalCommentId)||S.messages.find(m=>m.conversationId===c.id&&m.direction==='incoming');
 const parentId=root?.parentCommentId&&root.parentCommentId!==c.postId?root.parentCommentId:'';
 const m=parentId&&S.messages.find(m=>m.externalId===parentId&&S.conversations.find(x=>x.id===m.conversationId)?.connectionId===c.connectionId);
 return {conversationId:c.id,post:{text:c.postTitle||'',url:c.postUrl||'',createdAt:c.postCreatedAt||''},current:{likes:root?.likeCount??null},parentId,parent:m?{id:m.externalId,text:m.text,name:m.senderName||S.customers.find(p=>p.id===S.conversations.find(c=>c.id===m.conversationId)?.customerId)?.name,createdAt:m.createdAt,likes:m.likeCount??null}:null,errors:[]};
}
async function enhanceCommentContext(){
 if(route!=='comments')return;const slot=$('#comment-context-slot'),id=slot?.dataset.id;if(!id||commentContextLoading.has(id))return;
 const cached=commentContexts.get(id);if(cached&&Date.now()-Date.parse(cached.loadedAt||0)<60000)return;
 commentContextLoading.add(id);try{const data=await api('/comments/conversations/'+encodeURIComponent(id)+'/context');commentContexts.set(id,data);const current=$('#comment-context-slot');if(route==='comments'&&current?.dataset.id===id)current.innerHTML=commentContextHTML(data,commentReplyTargets.get(id)||'current');}catch(error){const current=$('#comment-context-slot');if(current?.dataset.id===id){let note=document.createElement('p');note.className='help-text';note.textContent=error.message;current.append(note);}}finally{commentContextLoading.delete(id);}
}

